import struct, json, zlib, os, sys, io
import numpy as np
from pygltflib import GLTF2

CT = {5120:('b',1),5121:('B',1),5122:('h',2),5123:('H',2),5125:('I',4),5126:('f',4)}
NT = {'SCALAR':1,'VEC2':2,'VEC3':3,'VEC4':4,'MAT4':16}

def accessor(g, blob, i):
    a=g.accessors[i]; bv=g.bufferViews[a.bufferView]
    comp,size=CT[a.componentType]; n=NT[a.type]
    off=(bv.byteOffset or 0)+(a.byteOffset or 0)
    stride=bv.byteStride or (size*n)
    out=np.empty((a.count,n),dtype={'b':np.int8,'B':np.uint8,'h':np.int16,'H':np.uint16,'I':np.uint32,'f':np.float32}[comp])
    for k in range(a.count):
        base=off+k*stride
        out[k]=np.frombuffer(blob[base:base+size*n],dtype=out.dtype,count=n)
    return out

def img_bytes(g, blob, i):
    im=g.images[i]; bv=g.bufferViews[im.bufferView]
    off=bv.byteOffset or 0
    data=blob[off:off+bv.byteLength]
    ext='png' if (im.mimeType or '').endswith('png') else 'jpg'
    return data, ext

def write_usdz(out_path, usda_text, tex_name, tex_bytes):
    files=[('model.usda', usda_text.encode('utf-8')), (tex_name, tex_bytes)]
    buf=io.BytesIO(); central=[]
    for name,data in files:
        nb=name.encode(); crc=zlib.crc32(data)&0xffffffff
        # align data start to 64 bytes via extra field padding
        header_end=buf.tell()+30+len(nb)
        pad=(-header_end)%64
        extra=b'\x00'*pad
        local_off=buf.tell()
        buf.write(struct.pack('<IHHHHHIIIHH',0x04034b50,20,0,0,0,0,crc,len(data),len(data),len(nb),len(extra)))
        buf.write(nb); buf.write(extra); buf.write(data)
        central.append((name,nb,crc,len(data),local_off))
    cd_start=buf.tell()
    for name,nb,crc,sz,off in central:
        buf.write(struct.pack('<IHHHHHHIIIHHHHHII',0x02014b50,20,20,0,0,0,0,crc,sz,sz,len(nb),0,0,0,0,0,off))
        buf.write(nb)
    cd_size=buf.tell()-cd_start
    buf.write(struct.pack('<IHHHHIIH',0x06054b50,0,0,len(central),len(central),cd_size,cd_start,0))
    with open(out_path,'wb') as f: f.write(buf.getvalue())

def fmt_pts(arr):
    return ', '.join('(%g, %g, %g)'%(p[0],p[1],p[2]) for p in arr)
def fmt_uv(arr):
    return ', '.join('(%g, %g)'%(p[0],p[1]) for p in arr)

def convert(glb_path, out_path, name, target_h=0.02):
    g=GLTF2().load(glb_path); blob=g.binary_blob()
    prim=g.meshes[0].primitives[0]
    P=accessor(g,blob,prim.attributes.POSITION).astype(np.float64)
    N=accessor(g,blob,prim.attributes.NORMAL).astype(np.float64) if prim.attributes.NORMAL is not None else None
    UV=accessor(g,blob,prim.attributes.TEXCOORD_0).astype(np.float64) if prim.attributes.TEXCOORD_0 is not None else None
    idx=accessor(g,blob,prim.indices).reshape(-1).astype(np.int64)
    # base color texture
    mat=g.materials[prim.material]; ti=mat.pbrMetallicRoughness.baseColorTexture.index
    src=g.textures[ti].source
    tex,ext=img_bytes(g,blob,src); tex_name=f'{name}_tex.{ext}'
    # scale+center: feet to y=0, center xz, height -> target_h
    mn=P.min(0); mx=P.max(0)
    h=mx[1]-mn[1]; s=target_h/h
    cx=(mn[0]+mx[0])/2; cz=(mn[2]+mx[2])/2
    P[:,0]=(P[:,0]-cx)*s; P[:,2]=(P[:,2]-cz)*s; P[:,1]=(P[:,1]-mn[1])*s
    ext_mn=P.min(0); ext_mx=P.max(0)
    if UV is not None:
        UV[:,1]=1.0-UV[:,1]
    fvc='[%s]'%(', '.join(['3']*(len(idx)//3)))
    fvi='[%s]'%(', '.join(map(str,idx.tolist())))
    pts='[%s]'%fmt_pts(P)
    nrm='[%s]'%fmt_pts(N) if N is not None else None
    st='[%s]'%fmt_uv(UV) if UV is not None else None
    usda=f'''#usda 1.0
(
    defaultPrim = "{name}"
    metersPerUnit = 1
    upAxis = "Y"
)

def Xform "{name}" (kind = "component")
{{
    def Mesh "geom"
    {{
        float3[] extent = [({ext_mn[0]:g}, {ext_mn[1]:g}, {ext_mn[2]:g}), ({ext_mx[0]:g}, {ext_mx[1]:g}, {ext_mx[2]:g})]
        int[] faceVertexCounts = {fvc}
        int[] faceVertexIndices = {fvi}
        point3f[] points = {pts}
        uniform token subdivisionScheme = "none"
'''
    if nrm:
        usda+=f'        normal3f[] primvars:normals = {nrm} (interpolation = "vertex")\n'
    if st:
        usda+=f'        texCoord2f[] primvars:st = {st} (interpolation = "vertex")\n'
    usda+=f'''        rel material:binding = </{name}/mat>
    }}

    def Material "mat"
    {{
