#!/usr/bin/env python3
"""
Little SuperClaws -- Meshy rig + animate pipeline.

Rigs each character once, applies walk + dance + idle clips, downloads the
animated GLBs (and a USDZ for the AR-default clip), then hands the animated
GLBs to glb2usdz.py for clean 2cm AR Quick Look files.

RUN:
    export MESHY_API_KEY=sk-...                 # required
    # optional: host the GLBs and set a base url; otherwise data-URI is used
    export MESHY_MODEL_BASE_URL=https://you.example.com/superclaws
    python3 meshy_pipeline.py

It is idempotent: completed steps are skipped if their output file already
exists, so you can re-run after a rate-limit (429) or network drop.
Source GLBs expected alongside this script: <name>_40k.glb (<=300k faces).
"""
import os, sys, time, json, base64, urllib.request, urllib.error

API   = "https://api.meshy.ai"
KEY   = os.environ.get("MESHY_API_KEY", "")
BASE_URL = os.environ.get("MESHY_MODEL_BASE_URL", "").rstrip("/")
HERE  = os.path.dirname(os.path.abspath(__file__))
OUT   = os.path.join(HERE, "meshy_out")
HEIGHT_M = 1.7          # rig height; final 2cm sizing handled at conversion
FPS = 30

# character -> {walk, dance, idle} action_ids (from meshy_rigging_spec.md)
CHARS = {
    "clawd":   {"walk": 121, "dance": 79, "idle": 36},
    "nessa":   {"walk": 107, "dance": 66, "idle": 255},
    "deirdre": {"walk": 106, "dance": 74, "idle": 12},
    "decklan": {"walk": 55,  "dance": 82, "idle": 11},
    "gerald":  {"walk": 123, "dance": 22, "idle": 36},
}
AR_DEFAULT = "idle"     # clip that also gets a fbx2usdz USDZ


def _req(method, path, body=None):
    url = path if path.startswith("http") else API + path
    data = json.dumps(body).encode() if body is not None else None
    req = urllib.request.Request(url, data=data, method=method)
    req.add_header("Authorization", f"Bearer {KEY}")
    if data:
        req.add_header("Content-Type", "application/json")
    for attempt in range(6):                       # backoff on 429/5xx
        try:
            with urllib.request.urlopen(req, timeout=120) as r:
                return json.loads(r.read().decode())
        except urllib.error.HTTPError as e:
            if e.code in (429, 500, 502, 503) and attempt < 5:
                wait = 2 ** attempt * 5
                print(f"   {e.code} -> backoff {wait}s"); time.sleep(wait); continue
            raise


def _poll(kind, task_id, every=8, timeout=900):
    t0 = time.time()
    while True:
        r = _req("GET", f"/openapi/v1/{kind}/{task_id}")
        st = r.get("status") or r.get("result", {}).get("status")
        if st == "SUCCEEDED":
            return r.get("result", r)
        if st in ("FAILED", "CANCELED", "EXPIRED"):
            raise RuntimeError(f"{kind} {task_id} -> {st}: {r}")
        if time.time() - t0 > timeout:
            raise TimeoutError(f"{kind} {task_id} timed out")
        print(f"   {kind} {task_id}: {st} ..."); time.sleep(every)


def _download(url, dest):
    req = urllib.request.Request(url)
    with urllib.request.urlopen(req, timeout=300) as r, open(dest, "wb") as f:
        f.write(r.read())
    print(f"   saved {os.path.basename(dest)} ({os.path.getsize(dest)/1e6:.1f} MB)")


def _model_ref(name):
    if BASE_URL:
        return {"model_url": f"{BASE_URL}/{name}_40k.glb"}
    glb = os.path.join(HERE, f"{name}_40k.glb")
    b64 = base64.b64encode(open(glb, "rb").read()).decode()
    return {"model_url": f"data:model/gltf-binary;base64,{b64}"}


def rig(name):
    rid_file = os.path.join(OUT, f"{name}.rig_id")
    if os.path.exists(rid_file):
        return open(rid_file).read().strip()
    print(f"[{name}] rigging ...")
    body = {**_model_ref(name), "height_meters": HEIGHT_M}
    rid = _req("POST", "/openapi/v1/rigging", body)["result"]
    _poll("rigging", rid)
    open(rid_file, "w").write(rid)
    return rid


def animate(name, clip, action_id, rig_task_id):
    glb = os.path.join(OUT, f"{name}_{clip}.glb")
    if os.path.exists(glb):
        print(f"[{name}] {clip}: already done"); return
    print(f"[{name}] {clip} (action {action_id}) ...")
    body = {"rig_task_id": rig_task_id, "action_id": action_id,
            "post_process": {"operation_type": "change_fps", "fps": FPS}}
    if clip == AR_DEFAULT:
        body["post_process"] = {"operation_type": "fbx2usdz"}
    aid = _req("POST", "/openapi/v1/animations", body)["result"]
    res = _poll("animations", aid)
    _download(res["animation_glb_url"], glb)
    if clip == AR_DEFAULT and res.get("processed_usdz_url"):
        _download(res["processed_usdz_url"], os.path.join(OUT, f"{name}_{clip}.usdz"))


def main():
    if not KEY:
        sys.exit("Set MESHY_API_KEY first (export MESHY_API_KEY=sk-...).")
    os.makedirs(OUT, exist_ok=True)
    for name, clips in CHARS.items():
        try:
            rid = rig(name)
            for clip, action_id in clips.items():
                animate(name, clip, action_id, rid)
                time.sleep(3)                      # be gentle on rate limits
        except Exception as e:
            print(f"!! {name} failed: {e} (re-run to resume)")
    print("\nDone. Animated GLBs in", OUT)
    print("Next: convert each animated GLB to 2cm USDZ via glb2usdz.py /")
    print("animate_usdz.py, or use the Meshy processed_usdz_url where present.")


if __name__ == "__main__":
    main()

